L000550	\section{Equations of motion}\label{Equations of motion}
L000551	We describe the behaviour of a slender shallow arch, where lateral displacements and twist rotations are not permitted, subjected to a point load acting on its midpoint; see Fig.~\ref{fig:schematic}.
L000552	The governing equations for the radial ($v^*$) and circumferential ($w^*$) displacements are given by~\cite{Trahair}
L000553	\begin{subequations}
L000554	\begin{align}
L000555	\label{PDEs Dimensional}
L000556	    &\rho^*\pdv[order=2]{v^*}{t^*}+\frac{E^* I^*_x}{A^*(R^*)^4}\pdv[order=4]{v^*}{\theta^*}-\frac{E^*}{(R^*)^2}\pdv{}{\theta^*}\left(\varepsilon_m\pdv{v^*}{\theta^*}\right)-\frac{E^*}{R^*}\varepsilon^*_m-\frac{P^*}{R^*A^*}\delta(\theta^*)=0, \\
L000557	    &\rho^*\pdv[order=2]{w^*}{t^*}-\frac{E^*}{R^*}\pdv{\varepsilon^*_m}{\theta^*}=0,
L000558	\end{align}
L000559	\end{subequations}
L000560	where $t^*$ is time, $\theta^*$ is the circumferential angle along the centreline of the arch,
L000561	$\rho^*$ is the mass density, $E^*$ is the Young's
L000562	modulus, $R^*$ is the arch radius, $A^*$ is the cross-sectional area, $I^*_x$ is the second area moment, $P^*$ is the applied load magnitude, and $\delta$ is the Dirac delta
L000563	function. These equations account for geometrical non-linearities while keeping the constitutive relationship linear~\cite{pi2002}.
L000564	The membrane (stretching) strain is given by
L000565	 \begin{equation}
L000566	     \varepsilon^*_m = \frac{1}{R^*}\pdv{w^*}{\theta^*} - \frac{v^*}{R^*} + \frac{1}{2(R^*)^2}\left(\pdv{v^*}{\theta^*} \right)^2.
L000567	     \label{eqn:em}
L000568	 \end{equation}
L000569	We add to these equations the following hinged boundary conditions,
L000570	\begin{equation}
L000571	    v^*(\pm\Theta,t^*)=\pdv[order=2]{v^*}{\theta}(\pm\Theta,t^*)=w^*(\pm\Theta,t^*)=0,
L000572	\end{equation}
L000573	where $2 \Theta \ll 1$ is the small opening angle of the arch.
L000574	The initial conditions are given by
L000575	\begin{equation}
L000576	    v^*(\theta^*,0) = V^*(\theta^*), \quad w^*(\theta^*,0) = W^*(\theta^*), \quad \pdv{v^*}{t}(\theta^*,0)=\pdv{w^*}{t^*}(\theta^*,0)=0,
L000577	\end{equation}
L000578	where $V^*$ and $W^*$ are initial radial and circumferential displacements.
L000579	We will later set $V^*$ and $W^*$ to be the
L000580	displacements associated with the
L000581	buckled state to determine the snap-through dynamics.  We will also introduce small
L000582	imperfections into the system by adding
L000583	perturbations to $V^*$ and $W^*$.
L000584	\begin{figure}
L000585	    \centering
L000586	    \includegraphics[width=0.35\linewidth]{Schematic.pdf}
L000587	    \caption{Sketch of an arch undergoing a snap-through instability due to a central point load.  The symbols $v^*(\theta^*,t^*)$ and $w^*(\theta^*,t^*)$ denote the radial and circumferential displacements, $P^*$ the applied load, $R^*$ the arch radius in the undeformed configuration, $\Theta$ half of the opening angle and $h^*$ the arch thickness. All terms marked with an asterisk are dimensional.}
L000588	    \label{fig:schematic}
L000589	\end{figure}
L000590	\subsection{Model non-dimensionalisation}
L000591	\label{sec:non-dim}
L000592	The governing equations are cast into dimensionless form by writing
L000593	\begin{align}\label{eq:nondimensionalization}
L000594	    \theta=\frac{\theta^*}{\Theta},\quad t=\frac{c^*}{R^*}\,t^*,\quad
L000595	    v = \frac{v^*}{R^*\Theta^2},\quad
L000596	    w = \frac{w^*}{R^*\Theta^3},\quad \varepsilon_m = \frac{\varepsilon^*_m}{\Theta^2},
L000597	    \quad
L000598	    P = \frac{(R^*)^2\Theta}{E^*I^*_x}P^*.
L000599	\end{align}
L000600	Using these expressions, the non-dimensional equations of motion are given by
L000601	\begin{subequations}
L000602	\label{PDEs}
L000603	\begin{align}
L000604	    &\pdv[order=2]{v}{t}+\frac{1}{\lambda^2}\pdv[order=4]{v}{\theta}-\pdv{}{\theta}\left(\varepsilon_m  \pdv{v}{\theta}\right)-\varepsilon_m-\frac{P}{\lambda^2}\delta(\theta)=0\label{radial PDE},\\
L000605	    &\pdv[order=2]{w}{t}-\pdv{\varepsilon_m}{\theta}=0\label{axial PDE},
L000606	\end{align}
L000607	\end{subequations}
L000608	where $\lambda$ is the modified slenderness defined as
L000609	\begin{equation}\label{lambda}
L000610	    \lambda = R^* \Theta^2 \sqrt{\frac{A^*}{I^*_x}}.
L000611	\end{equation}
L000612	The membrane strain is given by
L000613	\begin{equation}\label{eq:membranestrain}
L000614	    \varepsilon_m = \pdv{w}{\theta} - v +\frac{1}{2}\left(\pdv{v}{\theta}\right)^2.
L000615	\end{equation}
L000616	The dimensionless boundary conditions are
L000617	\begin{equation}
L000618	    v(\pm1,t)=\pdv[order=2]{v}{\theta}(\pm1,t)=w(\pm1,t)=0.
L000619	\end{equation}
L000620	The corresponding initial conditions are
L000621	\begin{align}
L000622	v(\theta,0)= V(\theta), \quad w(\theta,0)= W(\theta), \quad \pdv{v}{t}(\theta,0)=\pdv{w}{t}(\theta,0)=0.
L000623	\label{nd:ics}
L000624	\end{align}
L000625	Integrating \eqref{eq:membranestrain} and using the boundary conditions allows us to derive a compatibility condition, relating the change in length of the mid-line of the arch to the average membrane strain field, as
L000626	\begin{equation}\label{eq:compatibilityGeneral}
L000627	    \int_{-1}^1 \varepsilon_m\, \mathrm{d}\theta  = \int_{-1}^1\left[\frac{1}{2}\left(\pdv{v}{\theta}\right)^2-v\right]\, \mathrm{d}\theta.
L000628	\end{equation}
L000629	Examining the dimensionless model given by \eqref{eq:nondimensionalization}--\eqref{eq:compatibilityGeneral} shows that the dynamics of the arch are controlled
L000630	by two dimensionless parameters: the applied load $P$ and the
L000631	modified slenderness $\lambda$.
L000632	
L000633	\section{Bifurcation analysis}\label{Bifurcation analysis}
L000634	
L000635	The qualitative features of the solutions to the
L000636	dimensionless model given by \eqref{PDEs}--\eqref{nd:ics}
L000637	are determined through a bifurcation analysis.  This
L000638	involves computing the equilibrium configurations
L000639	of the system and examining their linear stability.
L000640	
L000641	\subsection{Equilibrium configurations}
L000642	\label{sec:equilibrium}
L000643	
L000644	The equilibrium configurations of the arch are obtained by
L000645	seeking solutions that are independent of time, which are denoted with a bar.
L000646	Equation \eqref{axial PDE} then implies that the equilibrium membrane strain $\bar{\varepsilon}_m$ is constant along the length of the arch.
L000647	Thus, we let
L000648	\begin{equation}\label{eq:strain_equilibrium}
L000649	    \bar{\varepsilon}_m=\pdv{\bar{w}}{\theta} - \bar{v} +\frac{1}{2}\left(\pdv{\bar{v}}{\theta}\right)^2 \equiv -\frac{\mu^2}{\lambda^2},
L000650	\end{equation}
L000651	where $\mu$ is a constant that is related to the force in the
L000652	circumferential direction~\cite{pi2002}.  The radial
L000653	force balance \eqref{radial PDE} reduces to
L000654	\begin{equation}\label{ODE Problem}
L000655	    \odv[order=4]{\bar{v}}{\theta}+\mu^2\odv[order=2]{\bar{v}}{\theta}+\mu^2=P\delta(\theta).
L000656	\end{equation}
L000657	There are two types of solutions to \eqref{eq:strain_equilibrium}--\eqref{ODE Problem} that are
L000658	characterised by different symmetry properties.  We define
L000659	\emph{symmetric} solutions as those which satisfy
L000660	\begin{align}
L000661	v(-\theta, t) = v(\theta, t),
L000662	\qquad
L000663	w(-\theta, t) = -w(\theta, t),
L000664	\label{eqn:eq_symmetry}
L000665	\end{align}
L000666	owing to the symmetry of the radial displacement about the arch midpoint.
L000667	The existence of symmetric solutions naturally follows from the
L000668	governing equations and can be verified through a change of
L000669	variable.  However, there are also
L000670	\emph{asymmetric} solutions that do not exhibit
L000671	any symmetry properties.  Asymmetric solutions are the result of spontaneous symmetry breaking
L000672	occurring at specific parameter combinations, as seen
L000673	by Pandey et al. \cite{Poppers} in the context of compressed
L000674	beams subject to a concentrated load.
L000675	While the symmetric solution occurs at all values of $\mu$, asymmetric solutions are admittable only for $\mu = \pi$ (for the loading condition considered here).
L000676	
L000677	For a symmetric equilibrium solution, the radial displacement $\bar{v}$  can be expressed in terms of the circumferential force $\mu$ and the applied load $P$ as
L000678	\begin{equation}
L000679	    \bar{v}(\theta) = A + B |\theta| -\frac{1}{2}\theta^2+C\cos(\mu\theta)+D\sin(\mu|\theta|)\label{v static sol},
L000680	\end{equation}
L000681	where
L000682	\begin{equation}
L000683	    A = \frac{\mu^2-P+2}{2\mu^2},\quad B = \frac{P}{2\mu^2}, \quad C = \frac{P\sin(\mu)-2\mu}{2\mu^3\cos(\mu)},\quad D = -\frac{P}{2\mu^3}.
L000684	    \label{eqn:ABCD}
L000685	\end{equation}
L000686	The circumferential displacement $\bar{w}$ can be obtained by
L000687	substituting \eqref{v static sol} into \eqref{eq:strain_equilibrium} and
L000688	solving for $\bar{w}$. To determine the constant $\mu$, we use the equilibrium configuration in \eqref{eq:compatibilityGeneral} to obtain
L000689	\begin{equation}\label{static comp cond}
L000690	    F(P,\mu,\lambda) = \frac{2\mu^2}{\lambda^2}+\int_{-1}^1\left[\frac{1}{2}\left(\pdv[order=1]{\bar{v}}{\theta}\right)^2-\bar{v}\right]\, \mathrm{d}\theta = 0.
L000691	\end{equation}
L000692	Upon substitution of the equilibrium solution for $\bar{v}$ given
L000693	by \eqref{v static sol} into \eqref{static comp cond}, a
L000694	nonlinear equation that determines the circumferential force
L000695	$\mu$ in terms of the applied load $P$ and the modified
L000696	slenderness $\lambda$ arises.
L000697	
L000698	The asymmetric equilibrium solution arises when
L000699	$\mu = \pi$ and is given by
L000700	\begin{equation}
L000701	    \bar{v}(\theta) = A + B |\theta| -\frac{1}{2}\theta^2+C\cos(\mu\theta)+E\sin(\mu\theta),
L000702	\end{equation}
L000703	where
L000704	$A$, $B$, and $C$ are given by \eqref{eqn:ABCD}
L000705	after substituting $\mu = \pi$.  The coefficient
L000706	$E$ is given by
L000707	\begin{align}
L000708	E = \begin{cases}
L000709	    K+\dfrac{P}{\pi^3},\wfor \theta<0, \\ K,\quad\quad\hspace{0.15cm}\wfor\theta\geq0,
L000710	    \end{cases}
L000711	\end{align}
L000712	where
L000713	\begin{equation}
L000714	    K = -\frac{3 \pi^{3} P \lambda +\sqrt{-144 \pi^{12}+24 \pi^{10} \lambda^{2}-27 P^{2} \pi^{6} \lambda^{2}-36 \pi^{8} \lambda^{2}+144 P \pi^{6} \lambda^{2}}}{6 \pi^{6} \lambda}.
L000715	\end{equation}
L000716	
L000717	
L000718	
L000719	\subsection{Linear stability analysis}
L000720	\label{sec:lsa}
L000721	The stability of the equilibria computed in Sec.~\ref{sec:equilibrium} can be assessed by
L000722	seeking a solution to the time-dependent model
L000723	given by
L000724	\begin{equation}
L000725	    \vec{u}(\theta, t) = \bar{\vec{u}}(\theta) + \epsilon \check{\vec{u}}(\theta)\,\e^{i \omega t}, \quad \varepsilon_m = \bar{\varepsilon}_m + \epsilon \check{\varepsilon}_m(\theta)\,\e^{i \omega t},
L000726	    \label{lsa:sol}
L000727	\end{equation}
L000728	where $\vec{u} = (v, w)$ is the non-dimensional displacement
L000729	vector, $\bar{\vec{u}}$ and $\bar{\varepsilon}_m$ are the equilibrium fields,
L000730	$\epsilon \ll 1$ is an arbitrary small parameter, and $\omega$ is a complex growth rate.
L000731	If $\omega$ is real then the system is expected
L000732	to oscillate about the equilibrium state; in this case, $\omega$
L000733	corresponds to one of the natural frequencies of the arch.
L000734	If $\omega$ is imaginary, then the perturbation to the equilibrium state will either grow or
L000735	decay, depending on the sign of the imaginary part of $\omega$.
L000736	Upon substitution of \eqref{lsa:sol} into \eqref{PDEs}--\eqref{nd:ics}, expanding about $\epsilon \ll 1$,
L000737	and neglecting small terms of $O(\epsilon^2)$, we find that the perturbations
L000738	$\check{\vec{u}} = (\check{v}, \check{w})$
L000739	and the growth rates $\omega$
L000740	are determined by the eigenproblem
L000741	\begin{equation}\label{first eigenproblem}
L000742	    \mathcal{L}\check{\vec{u}} = \omega^2\check{\vec{u}},
L000743	\end{equation}
L000744	where $\mathcal{L}$ is a matrix of linear differential operators given by
L000745	\begin{subequations}
L000746	\label{L operator}
L000747	\begin{align}
L000748	\mathcal{L} = \begin{pmatrix}
L000749	\mathcal{L}_{vv} & \mathcal{L}_{vw} \\
L000750	\mathcal{L}_{wv} & \mathcal{L}_{ww}
L000751	\end{pmatrix},
L000752	\end{align}
L000753	with
L000754	\begin{align}
L000755	\mathcal{L}_{vv} &=
L000756	        \frac{1}{\lambda^2}\odv[order=4]{}{\theta}+\left(\frac{\mu^2}{\lambda^2}-\left(\odv{\bar{v}}{\theta}\right)^2\right)\odv[order=2]{}{\theta}-\odv{\bar{v}}{\theta}\left(2\odv[order=2]{\bar{v}}{\theta}+1\right)\odv{}{\theta} - \left(\odv[order=2]{\bar{v}}{\theta}+1\right),
L000757	\\
L000758	\mathcal{L}_{vw} &= -\odv{\bar{v}}{\theta}\odv[order=2]{}{\theta}-\left(\odv[order=2]{\bar{v}}{\theta}+1\right)\odv{}{\theta},
L000759	\\
L000760	\mathcal{L}_{wv} &=
L000761	        \odv{}{\theta}-\odv[order=2]{\bar{v}}{\theta}\odv{}{\theta}-\odv{\bar{v}}{\theta}\odv[order=2]{}{\theta},
L000762	\\
L000763	\mathcal{L}_{ww} &= -\odv[order=2]{}{\theta}.
L000764	\end{align}
L000765	\end{subequations}
L000766	The boundary conditions for \eqref{first eigenproblem} are given
L000767	by
L000768	\begin{equation}
L000769	    \check{v}(\pm 1) = \odv[order=2]{\check{v}}{\theta}(\pm 1) = \check{w}(\pm 1) = 0.
L000770	    \label{lsa:bc}
L000771	\end{equation}
L000772	
L000773	It is straightforward to show that the linear operator $\mathcal{L}$
L000774	and boundary conditions \eqref{lsa:bc}
L000775	are self-adjoint with respect to the inner product
L000776	\begin{equation}\label{eq:inner-product}
L000777	    \langle \vec{u}, \vec{u}'\rangle = \int_{-1}^1 (v v' + w w')\,\text{d}\theta.
L000778	\end{equation}
L000779	Consequently, two different eigenmodes $\check{\vec{u}}_n$ and $\check{\vec{u}}_m$ with distinct eigenvalues $\omega_n^2 \neq \omega_m^2$
L000780	that satisfy $\mathcal{L} \check{\vec{u}}_n = \omega_n^2 \check{\vec{u}}_n$
L000781	and $\mathcal{L} \check{\vec{u}}_m = \omega_m^2 \check{\vec{u}}_m$
L000782	will be orthogonal. Thus, we can normalise the eigenmodes such that
L000783	$\langle \check{\vec{u}}_n, \check{\vec{u}}_m\rangle = \delta_{nm}$,
L000784	where $\delta_{nm}$ is the Kronecker delta.
L000785	
L000786	In general, the eigenproblem \eqref{first eigenproblem}--\eqref{lsa:bc} must be solved numerically.  We do this using a finite difference discretisation.  The eigenvalues of
L000787	the resulting sparse system are computed using
L000788	the {\tt eigs} function in SciPy.
L000789	The eigenvalues $\omega^2$ are
L000790	positive before snap-through occurs, implying the eigenmodes oscillate in time.  Snap-through occurs
L000791	when the smallest eigenvalue crosses zero
L000792	and becomes negative, resulting in
L000793	an exponentially growing and decaying
L000794	mode.
