L000796	\subsection{Symmetries of the eigenmodes}
L000797	
L000798	There are  two
L000799	types of symmetries that
L000800	manifest in the eigenmodes defined by the eigenvalue problem in \eqref{first eigenproblem}
L000801	when the equilibrium solution is \emph{symmetric} and hence satisfies
L000802	\eqref{eqn:eq_symmetry}.  In particular, by making the
L000803	substitution $\theta\to-\theta$, we find that the linear operator
L000804	$\mathcal{L}$ defined in \eqref{L operator} transforms according to
L000805	\begin{equation}\label{L symmetry eq}
L000806	    \mathcal{L} = \begin{pmatrix}
L000807	        \mathcal{L}_{vv} & \mathcal{L}_{vw} \\
L000808	        \mathcal{L}_{wv} & \mathcal{L}_{ww}
L000809	    \end{pmatrix}
L000810	    \to
L000811	    \begin{pmatrix}
L000812	        \mathcal{L}_{vv} & -\mathcal{L}_{vw} \\
L000813	        -\mathcal{L}_{wv} & \mathcal{L}_{ww}
L000814	    \end{pmatrix}.
L000815	\end{equation}
L000816	The transformation implies the existence of \emph{symmetric} eigenmodes
L000817	$\check{\vec{u}}^{S} = (\check{v}^{S}, \check{w}^S)$ that satisfy
L000818	\begin{align}
L000819	\mathcal{L}\check{\vec{u}}^S = \omega^S \check{\vec{u}}^S,
L000820	\quad
L000821	\check{v}^{S}(-\theta, t) = \check{v}^{S}(\theta, t),
L000822	\quad
L000823	\check{w}^{S}(-\theta, t) = -\check{w}^{S}(\theta, t),
L000824	\label{eqn:lin_symmetric}
L000825	\end{align}
L000826	and \emph{antisymmetric} eigenmodes $\check{\vec{u}}^{A}= (\check{v}^{A}, \check{w}^A)$ that satisfy
L000827	\begin{align}
L000828	\mathcal{L}\check{\vec{u}}^A = \omega^A\check{\vec{u}}^A,
L000829	\quad
L000830	\check{v}^{A}(-\theta, t) = -\check{v}^{A}(\theta, t),
L000831	\quad
L000832	\check{w}^{A}(-\theta, t) = \check{w}^{A}(\theta, t).
L000833	\label{eqn:lin_asymmetric}
L000834	\end{align}
L000835	If we let $\{\check{\vec{u}}^S_m\}$ and
L000836	$\{\check{\vec{u}}^A_n\}$ denote all of the
L000837	symmetric and antisymmetric eigenmodes, then
L000838	orthogonality implies that
L000839	$\langle \check{\vec{u}}^{S}_m, \check{\vec{u}}^S_{m'} \rangle = \delta_{mm'}$,
L000840	$\langle \check{\vec{u}}^{S}_m, \check{\vec{u}}^A_{n} \rangle = 0$, and
L000841	$\langle \check{\vec{u}}^{A}_n, \check{\vec{u}}^A_{n'} \rangle = \delta_{nn'}$ for all values of
L000842	$n$, $n'$, $m$, and $m'$.
