L000903	\subsection{Calculation of the critical eigenmodes}
L000904	\label{sec:criticalmodes}
L000905	
L000906	The snap-through configurations of the system can be
L000907	determined by seeking parameter combinations
L000908	that lead to a zero eigenvalue ($\omega = 0$)
L000909	in the eigenproblem \eqref{first eigenproblem}--\eqref{lsa:bc}.
L000910	The critical eigenmode at snap-through associated with the zero eigenvalue is called a \emph{critical mode}, and will be denoted with a $0$ subscript.  The critical modes
L000911	(or, equivalently, the snap-through configurations) can be obtained
L000912	by solving
L000913	\begin{equation}
L000914	    \mathcal{L}\tilde{\vec{u}}_0=\boldsymbol{0},
L000915	\end{equation}
L000916	where $\mathcal{L}$ is given by \eqref{L operator}.  However, it
L000917	is more convenient to instead calculate the critical modes by
L000918	linearising the equations that define the equilibrium solutions,
L000919	since setting $\omega = 0$ corresponds to seeking a time-independent
L000920	solution.
L000921	 We find that
L000922	$\partial \tilde{\varepsilon}_{0} / \partial \theta = 0$ and hence
L000923	the perturbation to the membrane strain, $\tilde{\varepsilon}_{0}$, is
L000924	uniform in space.  The $O(\epsilon)$ contributions to
L000925	\eqref{radial PDE} and \eqref{eq:compatibilityGeneral} reduce to
L000926	\begin{subequations}
L000927	\begin{align}\label{zero eigenvalue problem}
L000928	    &\odv[order=4]{\tilde{v}_{0}}{\theta}+\mu^2\odv[order=2]{\tilde{v}_{0}}{\theta}=\lambda^2\tilde{\varepsilon}_{0}\left(\odv[order=2]{\bar{v}}{\theta}+1\right), \\
L000929	    & \tilde{\varepsilon}_{0}=\frac{1}{2}\int^1_{-1}\left(\odv{\bar{v}}{\theta}\odv{\tilde{v}_{0}}{\theta}-\tilde{v}_{0}\right)\text{d}\theta,
L000930	    \label{zero eigenvalue comp cond}
L000931	\end{align}
L000932	\end{subequations}
L000933	respectively. Due to the possibility of
L000934	asymmetric equilibrium when $\mu = \pi$, and symmetric equilibria for any $\mu$, we must consider these two cases separately. As highlighted in the previous section, $\bar{v}$ is always symmetric and given by \eqref{v static sol}.
L000935	
L000936	\subsubsection{Limit-point buckling}
L000937	If $\mu \neq \pi$, the perturbations to the displacement field are given by
L000938	\begin{subequations}\label{zero eigmodes}
L000939	\begin{align}
L000940	    &\tilde{v}_{0}(\theta) = V^s_1+V^s_2|\theta|+(V^s_3+V^s_4|\theta|)\cos(\mu\theta)+(V^s_5+V^s_6|\theta|)\sin(\mu|\theta|), \\
L000941	    &\tilde{w}_{0}(\theta) = \iint \left(\odv{v_0}{\theta} - \odv[order=2]{\bar{v}}{\theta}\odv{v_0}{\theta}-\odv{\bar{v}}{\theta}\odv[order=2]{v_0}{\theta}\right)\text{d}\theta\,\text{d}\theta + W^s_1+W^s_2\theta,
L000942	\end{align}
L000943	\end{subequations}
L000944	with
L000945	\begin{subequations}
L000946	\begin{align}
L000947	    V^s_1 &= \frac{2-P}{2\mu^4},
L000948	    \\
L000949	    V^s_2 &= \frac{P}{2\mu^4},
L000950	    \\
L000951	    V^s_3 &= \frac{3P\sin(\mu)\cos(\mu)+2\sin(\mu)\mu^2-4\mu\cos(\mu)-P\mu}{4\mu^5\cos(\mu)^2},
L000952	    \\
L000953	    V^s_4 &= \frac{P}{4\mu^4},
L000954	    \\
L000955	    V^s_5 &= -\frac{3P}{4\mu^5},
L000956	    \\
L000957	    V^s_6 &= \frac{P\sin(\mu)-2\mu}{4\mu^4\cos(\mu)},
L000958	    \\
L000959	    W^s_1 &= \frac{P\left(P\mu+8\mu\cos(\mu)-2\sin(\mu)\mu^2-5P\sin(\mu)\cos(\mu)\right)}{8\mu^7\cos(\mu)},
L000960	    \\
L000961	W^s_2 &= \frac{W^s_{21} + W^2_{22}}{32 \mu^7 \cos (\mu)^3}, \\
L000962	W^s_{21} &= 4 \mu\left(P^2-8 P+4(2-P) \mu^2\right) \cos (\mu)^3 \nonumber \\ &\quad +\left(4 P\left(\mu^2+8\right) \mu-3\left(5 P^2+2 \mu^2\right) \sin (\mu)\right) \cos (\mu)^2, \\
L000963	W^s_{22} &=  \left(P^2 \mu+4 \mu^3-4 P \mu^2 \sin (\mu)\right) \cos (\mu) +2\left(P^2 \mu^2+4 \mu^4\right) \sin (\mu)-8 P \mu^3.
L000964	\end{align}
L000965	\end{subequations}
L000966	It can be easily checked that
L000967	\begin{align}
L000968	\tilde{v}_{0}(-\theta,t) = \tilde{v}_{0}(\theta, t),
L000969	\qquad
L000970	\tilde{w}_{0}(-\theta, t) = -\tilde{w}_{0}(\theta, t),
L000971	\end{align}
L000972	thus describing a symmetric critical mode.
L000973	
L000974	\subsubsection{Bifurcation buckling}
L000975	For the special case when $\mu=\pi$, the solution of eq.~\eqref{zero eigenvalue problem} implies $\tilde{\varepsilon}_{0} = 0$. The corresponding displacements are given by
L000976	\begin{subequations}\label{Other zero eigenmodes}
L000977	\begin{align}
L000978	    \tilde{v}_{0}(\theta) &= \sin(\pi\theta), \\
L000979	    \tilde{w}_{0}(\theta) &= W^a_1+W^a_2|\theta| + (W^a_3+|\theta|)\sin(\pi|\theta|)+(W_4^a\cos(\pi\theta)+W_5^a\sin(\pi|\theta|))\cos(\pi\theta),
L000980	\end{align}
L000981	\end{subequations}
L000982	where
L000983	\begin{gather}
L000984	    W_1^a = \frac{2-P}{4\pi},\quad W_2^a = \frac{P}{4\pi},\quad W_3^a = -\frac{P}{2\pi^2},\quad W_4^a = -\frac{1}{2\pi},\quad W^a_5 = \frac{P}{4\pi^2}.
L000985	\end{gather}
L000986	It can be easily checked that
L000987	\begin{align}
L000988	\tilde{v}_{0}(-\theta,t) = -\tilde{v}_{0}(\theta, t),
L000989	\qquad
L000990	\tilde{w}_{0}(-\theta, t) = \tilde{w}_{0}(\theta, t),
L000991	\end{align}
L000992	thus describing an antisymmetric critical mode.
L000993	
L000994	In the following sections, we develop our theory using orthonormal eigenfunctions, so we normalize the eigenfunctions in \eqref{zero eigmodes} and \eqref{Other zero eigenmodes} as
L000995	\begin{equation}
L000996	    \check{v}_0(\theta) = \frac{\tilde{v}_0(\theta)}{\langle\tilde{\vec{u}}_0,\tilde{\vec{u}}_0\rangle},
L000997	    \qquad
L000998	    \check{w}_0(\theta) = \frac{\tilde{w}_0(\theta)}{\langle\tilde{\vec{u}}_0,\tilde{\vec{u}}_0\rangle},
L000999	\end{equation}
L001000	where $\langle\cdot,\cdot\rangle$ is the inner product defined in \eqref{eq:inner-product}.
