L001002	\section{Numerical simulations}\label{sec:Numerics}
L001003	
L001004	The non-dimensional model given by
L001005	\eqref{PDEs}--\eqref{nd:ics} is numerically
L001006	solved using the Python package FEniCS \cite{FEniCS}, which is an
L001007	open-source finite element library.  The weak
L001008	form of the governing equations is discretised
L001009	in space using 1000 nodes.  The solution is
L001010	represented using piecewise linear elements
L001011	(e.g.\ linear continuous Galerkin elements).
L001012	The system was discretised in time using the
L001013	generalised-$\alpha$ method, which is second-order accurate in time and dampens high-frequency modes~\cite{GeneralisedAlphaMethod}.
L001014	The resulting nonlinear system of algebraic
L001015	equations is solved using Newton's method
L001016	at each time step.  The sparse direct solver MUMPS was used to
L001017	solve the linear systems formed by each Newton iteration.
L001018	
L001019	\section{Multiple-scales analysis of snap-through}\label{sec:MS}
L001020	
L001021	To gain analytical insights into the snap-through
L001022	dynamics of the arch and to rigorously  calculate the snap-through time, we use the method of multiple scales~\cite{kevorkian1996multiple}. We assume that the system is initially at the snap-through configuration, associated with an applied load $P_{cr}$. Snap-through is then triggered by adding a small increment to the critical applied load.  Thus, we let
L001023	\begin{equation}
L001024	    P = P_{cr}(1+\DP), \quad \DP\ll 1.
L001025	\end{equation}
L001026	We then look for solutions of the form
L001027	\begin{gather}\label{eq:expansions}
L001028	    \vec{u}(\theta,t) = \vec{u}_{cr}(\theta) + \DP \hat{\vec{u}}(\theta, t),
L001029	    \qquad
L001030	    \varepsilon_m(\theta,t) = \varepsilon_{cr} + \DP\hat{\varepsilon}(\theta,t).
L001031	\end{gather}
L001032	Substituting these expressions into eq. \eqref{PDEs} and \eqref{eq:membranestrain}, we obtain the governing problem for the perturbations $\hat{\boldsymbol{u}}$ and $\hat{\varepsilon}$ as
L001033	\begin{subequations}\label{Asymptotic PDEs}
L001034	\begin{gather}
L001035	    \pdv[order=2]{\hat{v}}{t}+\frac{1}{\lambda^2}\pdv[order=4]{\hat{v}}{\theta}- \varepsilon_{cr}\pdv[order=2]{\hat{v}}{\theta} - \odv{\overline{v}_{cr}}{\theta}\pdv{\hat{\varepsilon}}{\theta}-{\hat{\varepsilon}}\left(\odv[order=2]{\overline{v}_{cr}}{\theta}+1\right)-\DP\left(\pdv{\hat{\varepsilon}}{\theta}\pdv{\hat{v}}{\theta}+{\hat{\varepsilon}} \pdv[order=2]{\hat{v}}{\theta}\right)=\frac{P_{cr}\delta(\theta)}{\lambda^2}, \\
L001036	    \pdv[order=2]{\hat{w}}{t}=\pdv{\hat{\varepsilon}}{\theta},\\{\hat{\varepsilon}} = \pdv{\hat{w}}{\theta}-{\hat{v}}+\odv{\overline{v}_{cr}}{\theta}\pdv{\hat{v}}{\theta}+\frac{1}{2}\DP\left(\pdv{\hat{v}}{\theta}\right)^2.
L001037	\end{gather}
L001038	\end{subequations}
L001039	By eliminating $\hat{\varepsilon}$, the system \eqref{Asymptotic PDEs}
L001040	can be written in a compact vector form as
L001041	\begin{equation}\label{Order 1 nonlinear eq}
L001042	     \pdv[order=2]{\hat{\boldsymbol{u}}}{t}+\mathcal{L} {\hat{\boldsymbol{u}}} = \DP \mathcal{N}({\hat{\boldsymbol{u}}})+\delta(\theta) {\boldsymbol{F}},
L001043	\end{equation}
L001044	where $\mathcal{L}$ is the linear differential operator defined by \eqref{L operator}, $\mathcal{N}$ is a nonlinear differential operator, and $\vec{F} = (P_{cr} / \lambda^2, 0)$.  The initial conditions in eq.~\eqref{nd:ics} become
L001045	\begin{equation}\label{eq:ic_hat}
L001046	    \hat{\vec{u}}(\theta,0) = 0, \quad \frac{\partial  \hat{\vec{u}}}{\partial t}(\theta,0)  = 0.
L001047	\end{equation}
L001048	The
L001049	operator $\mathcal{N}$ can be expressed as
L001050	the sum of a bilinear and trilinear operator,
L001051	\begin{align}
L001052	\mathcal{N}(\vec{u}) = \mathcal{B}(\vec{u}, \vec{u}) + \DP\, \mathcal{T}(\vec{u}, \vec{u}, \vec{u}),
L001053	\end{align}
L001054	where
L001055	\begin{align}
L001056	\mathcal{B}(\vec{u}, \vec{u}) = \begin{pmatrix}
L001057	        3\odv{\overline{v}_{cr}}{\theta}\pdv{v}{\theta}\pdv[order=2]{v}{\theta}+\frac{1}{2}\left(3\odv[order=2]{v _{cr}}{\theta}-1\right)\left(\pdv{v}{\theta}\right)^2-v\pdv{v}{\theta}+\pdv{v}{\theta}\pdv[order=2]{w}{\theta}+\pdv[order=2]{v}{\theta}\pdv{w}{\theta} \\ \pdv{v}{\theta}\pdv[order=2]{v}{\theta}
L001058	    \end{pmatrix}
L001059	\end{align}
L001060	and
L001061	\begin{align}
L001062	\mathcal{T}(\vec{u}, \vec{u}, \vec{u})  = \begin{pmatrix}
L001063	        \frac{3}{2}\left(\pdv{v}{\theta}\right)^2\pdv[order=2]{v}{\theta} \\ 0
L001064	    \end{pmatrix}.
L001065	\end{align}
L001066	
L001067	By using the symmetries of the modes of $\mathcal{L}$ discussed in Sec.~\ref{sec:lsa}, we write the solution to \eqref{Order 1 nonlinear eq} in terms of an eigenfunction expansion decomposed into symmetric and antisymmetric eigenmodes as
L001068	\begin{align}
L001069	\hat{\vec{u}}(\theta, t) =
L001070	\sum_{n \in \mathbb{S}} S_n(t) \check{\vec{u}}_n^S(\theta) +
L001071	\sum_{m \in \mathbb{A}} A_m(t) \check{\vec{u}}_m^A(\theta),
L001072	\label{eqn:u_expansion}
L001073	\end{align}
L001074	where superscript $S$ indicates symmetric eigenmodes, superscript $A$ indicates antisymmetric eigenmodes,  $S_n$ and $A_m$ are amplitudes of symmetric and antisymmetric modes, respectively, and $\mathbb{S}$ and $\mathbb{A}$ are sets that contain
L001075	the indices of the symmetric and antisymmetric modes (which will be
L001076	specified when pertinent).
L001077	
L001078	
L001079	
L001080	
L001081	Substituting \eqref{eqn:u_expansion} into \eqref{Order 1 nonlinear eq} and then
L001082	taking inner products with symmetric and antisymmetric eigenmodes
L001083	leads to a nonlinear system of equations for the amplitudes
L001084	given by
L001085	\begin{subequations}
L001086	\label{eqn:ode_as}
L001087	\begin{align}
L001088	\tdd{S_n}{t} + (\omega_n^S)^2 S_n &= F_n +\DP\left\langle\mathcal{N}(\hat{\vec{u}}),\check{\vec{u}}_n^S\right\rangle,  \\
L001089	\tdd{A_m}{t} + (\omega_m^A)^2 A_m &=  \DP\left\langle\mathcal{N}(\hat{\vec{u}}),\check{\vec{u}}_m^A\right\rangle,
L001090	\end{align}
L001091	\end{subequations}
L001092	where $F_n = \langle \vec{F}\delta(\theta), \check{\vec{u}}^S_n \rangle$. From \eqref{eqn:ode_as}, we see that the symmetric nature of the point load only directly excites the symmetric modes.
L001093	Growth of antisymmetric modes can only happen
L001094	via non-linear interactions.
L001095	When written using the same eigenfunction expansion, the initial conditions in eq.~\eqref{eq:ic_hat} become
L001096	\begin{align}\label{eq:ic_as}
L001097	S_n(0) = 0, \quad \td{S_n}{t}(0) = 0, \quad A_m(0) = 0, \quad \td{A_m}{t}(0) = 0.
L001098	\end{align}
L001099	These conditions represent an ideal scenario where
L001100	snap-through happens from exactly the equilibrium configuration that becomes unstable at the bifurcation.  In our analysis, we highlight how ideal initial conditions lead to very different behaviour when applied to the limit-point and bifurcation buckling.
L001101	
L001102	For convenience, we introduce the quantities obtained by taking the inner product between the bilinear and trilinear forms and the eigenmodes of $\mathcal{L}$:
L001103	\begin{equation}
L001104	    \N{nmk}^{IJK} := \langle \mathcal{B}(\check{\vec{u}}^I_n,\check{\vec{u}}^J_m),\check{\vec{u}}^K_k \rangle,
L001105	    \qquad
L001106	    \Nt{nmsk}^{IJKL} := \langle \mathcal{T}(\check{\vec{u}}^I_n,\check{\vec{u}}^J_m,\check{\vec{u}}^K_s),\check{\vec{u}}^L_k \rangle,
L001107	\end{equation}
L001108	where the superscripts $I,J,K,L\in\{A,S\}$ are used to identify the symmetries of the eigenmodes denoted by the subscripts $n,m,k,s$. Due of the symmetries in the problem, it can be shown that
L001109	\begin{subequations}
L001110	\label{eqn:sym_simp}
L001111	\begin{align}
L001112	\mathcal{B}_{nmk}^{SSA} = \left\langle\mathcal{B}\left(\check{\vec{u}}_n^S,\check{\vec{u}}_{m}^S\right),\check{\vec{u}}_k^A\right\rangle=0,\\
L001113	\mathcal{T}_{nmks}^{SSSA} = \left\langle\mathcal{T}\left(\check{\vec{u}}_n^S,\check{\vec{u}}_{m}^S,\check{\vec{u}}_{k}^S\right),\check{\vec{u}}_s^A\right\rangle=0,
L001114	\end{align}
L001115	\end{subequations}
L001116	which will be used in the analysis.
L001117	
L001118	\subsection{Analysis of limit-point buckling}\label{sec:LP}
L001119	
L001120	Limit-point buckling occurs when the critical eigenvalue $\omega_0=0$ is associated with a symmetric eigenmode $\check{\vec{u}}_0=\check{\vec{u}}_0^S$. Without loss of generality, we rearrange the remaining eigenvalues in increasing order as $0 < \omega_1^S < \omega_2^S < \ldots$ and $0 < \omega_1^A < \omega_2^A < \ldots$,
L001121	implying that $\mathbb{S} = \{0, 1, 2, \ldots\}$
L001122	and $\mathbb{A} = \{1, 2, \ldots \}$.
L001123	
L001124	\subsubsection{The origin of multiple time scales}
L001125	We first consider a standard asymptotic expansion of the amplitudes of the symmetric and antisymmetric modes as
L001126	\begin{subequations}
L001127	\label{eq:wnl_expansion}
L001128	\begin{align}
L001129	    S_n(t)&=\sum_{k=0}^{\infty}\DP^k S_n^{(k)}(t), \\
L001130	    A_m(t)&=\sum_{k=0}^{\infty}\DP^k A_m^{(k)}(t).
L001131	\end{align}
L001132	\end{subequations}
L001133	After inserting \eqref{eq:wnl_expansion} in eq.~\eqref{eqn:ode_as}, with initial conditions in eq.~\eqref{eq:ic_as}, we then expand in powers of $\Delta P$.  By collecting terms at each order of $\Delta P$, a hierarchy of linear systems of ordinary differential equations can be formulated and then solved.
L001134	
L001135	From the $O(1)$ problem, we obtain the solution
L001136	\begin{subequations} \label{Sym sol}
L001137	\begin{alignat}{2}\label{Sym quad sol}
L001138	    \St{0}{0}{t} &= F_0t^2,\\
L001139	    \St{n}{0}{t} &= \frac{F_n}{(\omega^S_n)^2}\left(1-\cos(\omega_n^St)\right),\\
L001140	    \A{n}{0}{t} &= 0,
L001141	\end{alignat}
L001142	\end{subequations}
L001143	for $n = 1, 2, \ldots$.
L001144	In deriving \eqref{Sym sol}, it was assumed that the
L001145	nonlinear term $\DP\left(\St{0}{0}\right)^2$ remains
L001146	small.  Due to the quadratic growth of $\St{0}{0}$,
L001147	this nonlinear term will become $O(1)$ in size when $t = O(\DP^{-1/4})$, at which point the amplitude of the critical mode is given by $\St{0}{0} = O(\DP^{-1/2})$ and the solution \eqref{Sym quad sol} is no longer valid.
L001148	By resolving the solution on $O(1)$ time scales using asymptotic methods, we have systematically derived the scales needed to capture the nonlinear (snap-through) behaviour, which are the same as those proposed ad hoc for an equivalent snap-through problem in \cite{Gomez2016} and confirmed numerically in \cite{Radisson_2023}.
L001149	
L001150	
L001151	\subsubsection{Multiple-scale expansion}
L001152	To simultaneously account for the oscillatory dynamics on an $O(1)$ time scale and the nonlinear growth of the
L001153	critical mode on an $O(\DP^{-1/4})$ time scale,
L001154	we introduce a new slow time variable given by
L001155	$\tau = \DP^{1/4}t$.
L001156	Moreover, we expand the amplitudes as
L001157	$S_0 \sim \DP^{-1/2}\bar{S}_0^{(0)}(\tau) + \bar{S}_{0}^{(1)}(t, \tau) + \ldots$,
L001158	$S_n \sim \bar{S}_n^{(0)}(t, \tau) + \ldots$ and
L001159	$A_n \sim \bar{A}_n^{(0)}(t, \tau) + \ldots$ for
L001160	$n = 1, 2, \ldots$.
L001161	The leading-order contribution to the evolution
L001162	equation for the critical amplitude is
L001163	\begin{equation}
L001164	     \pdv[order=2]{\bar{S}_0^{(1)}}{t} =  \left(\bar{S}_0^{(0)}\right)^2 \mathcal{B}^{SSS}_{000}+F_0 - \odv[order=2]{\bar{S}_0^{(0)}}{\tau},
L001165	\end{equation}
L001166	with homogeneous initial conditions. To suppress secular terms, we set the right-hand side (RHS) to zero to obtain
L001167	\begin{equation}\label{Sym amplitude eq}
L001168	    \odv[order=2]{\bar{S}_0^{(0)}}{\tau} = r_{\text{LP}}+q_{\text{LP}} \left(\bar{S}_0^{(0)}\right)^2,
L001169	\end{equation}
L001170	where
L001171	\begin{equation}
L001172	    r_{\text{LP}} = F_0,\wand q_{\text{LP}} =\N{000}^{SSS}.
L001173	\end{equation}
L001174	The implict solution to \eqref{Sym amplitude eq} with homogeneous initial conditions is given by
L001175	\begin{equation}
L001176	    \tau = \sqrt{\frac{3}{2}}\int_0^{\bar{S}_0^{(0)}(\tau)} \frac{\text{d}\xi}{\sqrt{3r_{\text{LP}}\xi+q_{\text{LP}}\xi^3}}.
L001177	\end{equation}
L001178	By taking the limit for $\bar{S}_0^{(0)}\to\infty$, the finite snap-through time can be computed as
L001179	\begin{equation}
L001180	    \tau_\text{snap}
L001181	    = \left(\frac{3}{64\pi^2r_{\text{LP}}q_{\text{LP}}}\right)^\frac{1}{4}\Gamma\left(\frac{1}{4}\right)^2,
L001182	\end{equation}
L001183	or, in the original (non-dimensional) time variable, as
L001184	\begin{equation}\label{Symmetric snap-through time}
L001185	    t_\text{snap}^{\text{LP}} = \left(\frac{3}{64\pi^2r_{\text{LP}}q_{\text{LP}}\DP}\right)^\frac{1}{4}\Gamma\left(\frac{1}{4}\right)^2.
L001186	\end{equation}
L001187	The limit-point snap-through time given by \eqref{Symmetric snap-through time} is equivalent to the one derived in \cite{Gomez2016} for the case of the compressed beam. Because the critical mode $\check{\vec{u}}^S_0 $ can be found analytically, the coefficients $r_{\text{LP}}$ and $q_{\text{LP}}$ can be derived in an exact form and their dependence on $\lambda$ can be found explicitly. As shown in Fig. \ref{fig:qr_limitpoint}, the quantity $r_{\text{LP}}q_{\text{LP}}$ remains approximately constant in the region where the arch undergoes limit-point buckling. The expression in \eqref{Symmetric snap-through time} is thus independent of $\lambda$, as discussed in the main text.
L001188	In this mode of snap-through, the load acts directly on the critical mode via $F_0$, which ensures that snap-through occurs even when considering the ideal initial conditions.
L001189	
