L001193	    \includegraphics[width=0.8\linewidth]{r_q_plot_LP.pdf}
L001194	    \caption{Quantities (a) $r_\text{LP}$, (b) $q_\text{LP}$ and (c) the product $r_\text{LP}q_\text{LP}$ for the interval of $\lambda$ where the arch undergoes limit-point buckling.}
